<template><section v-loading="loading"><div class="toolbar"><el-button type="primary" @click="open">登记付款</el-button><el-button @click="load">刷新</el-button></div><el-card shadow="never"><el-table :data="payments"><el-table-column prop="payment_no" label="付款单号" min-width="190" /><el-table-column prop="payee_name" label="收款方" /><el-table-column label="金额" width="140"><template #default="{row}">{{formatMoney(row.amount)}}</template></el-table-column><el-table-column prop="payee_account_masked" label="账号" /><el-table-column prop="status" label="状态" width="110" /><el-table-column prop="bank_reference" label="银行流水" /><el-table-column label="操作" width="130"><template #default="{row}"><el-button v-if="row.status==='pending'" size="small" type="success" @click="confirm(row)">确认付款</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="登记待付款" width="540px"><el-form label-width="90px"><el-form-item label="报销单"><el-select v-model="form.reimbursement_id"><el-option v-for="item in approved" :key="item.id" :label="`${item.reimbursement_no} · ${formatMoney(item.total_amount)}`" :value="item.id" /></el-select></el-form-item><el-form-item label="收款方"><el-input v-model="form.payee_name" /></el-form-item><el-form-item label="收款账号"><el-input v-model="form.payee_account" show-password /></el-form-item><el-form-item label="计划付款"><el-date-picker v-model="form.scheduled_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{financeApi,formatMoney,type Payment,type Reimbursement}from'@/api/finance';const loading=ref(false),dialog=ref(false),payments=ref<Payment[]>([]),approved=ref<Reimbursement[]>([]);const form=reactive({reimbursement_id:'',payee_name:'',payee_account:'',scheduled_at:''});async function load(){loading.value=true;try{[payments.value,approved.value]=await Promise.all([financeApi.payments(),financeApi.reimbursements('approved')])}finally{loading.value=false}}async function open(){await load();form.reimbursement_id=approved.value[0]?.id||'';dialog.value=true}async function create(){await financeApi.createPayment({...form,scheduled_at:form.scheduled_at||null});dialog.value=false;ElMessage.success('待付款已登记');await load()}async function confirm(payment:Payment){const{value}=await ElMessageBox.prompt('输入银行流水号','确认付款',{inputValidator:v=>!!v||'流水号不能为空'});await financeApi.confirmPayment(payment.id,{version:payment.lock_version,bank_reference:value,paid_at:new Date().toISOString()});ElMessage.success('付款已确认并计入支出');await load()}onMounted(load)</script>
<style scoped>.toolbar{display:flex;gap:10px;margin-bottom:16px}</style>
